/**
 * The text of `__golden__/expected.ts`: the goldens of every case, written exactly as the update command saves them.
 * Design: docs/09-engineering/testing.md §Sim goldens.
 * Invariants: the output depends only on the results and is stable (one hash per line, cases in the order given),
 * so a regenerated file differs from the committed one only when a golden really changed.
 */

import type { GoldenResult } from './scripted';

/** A scripted golden as committed: the hashes, the final hash and the event count (always 0 until the scheduler exists). */
export type ExpectedGolden = GoldenResult & { readonly eventCount: number };

export type NamedResult = { readonly name: string; readonly result: GoldenResult };

const HEADER = `/**
 * Goldens of the scripted scenarios in cases.ts. GENERATED by \`pnpm golden:update\`; never edit by hand.
 * A golden changes only with a RULES_VERSION bump, in the same commit, with the reason (docs/09-engineering/testing.md).
 * \`eventCount\` is 0 for scripted scenarios because they run without the scheduler's event log; slice 2 (programs
 * through the real engine) fills it from the engine.
 */

import type { ExpectedGolden } from '../golden/format';

// prettier-ignore
export const expected: Readonly<Record<string, ExpectedGolden>> = {
`;

function entry({ name, result }: NamedResult): string {
  const hashes = result.hashes.map((h) => `      ${h},\n`).join('');
  return `  '${name}': {\n    hashes: [\n${hashes}    ],\n    finalStateHash: ${result.finalStateHash},\n    eventCount: 0,\n  },\n`;
}

/** The full text of expected.ts for these results. */
export function formatExpected(results: readonly NamedResult[]): string {
  return `${HEADER}${results.map(entry).join('')}};\n`;
}
